      <Tab value="items" label={`Предметы (${inventory.filter((item) => item.kind === 'cosmetic').length})`} />
    </Tabs>
    {error && <Alert severity="error">{error}</Alert>}
    {workflowError && <Alert severity="error">{workflowError}</Alert>}
